import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.Dhf_H6O0.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/index.md","filePath":"troubleshooting/index.md"}'),i={name:"troubleshooting/index.md"};function n(r,e,l,h,c,d){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Find your issue below. Each section explains what you see, why it happens, and how to fix it.</p><h2 id="docker-issues" tabindex="-1">Docker issues <a class="header-anchor" href="#docker-issues" aria-label="Permalink to &quot;Docker issues&quot;">​</a></h2><h3 id="docker-desktop-is-not-installed" tabindex="-1">Docker Desktop is not installed <a class="header-anchor" href="#docker-desktop-is-not-installed" aria-label="Permalink to &quot;Docker Desktop is not installed&quot;">​</a></h3><p><strong>What you see:</strong> The Dashboard shows a red DOCKER indicator and the message &quot;Docker Desktop is not installed.&quot;</p><p><strong>Fix:</strong></p><ol><li>Click <strong>Install Docker Desktop</strong> — MCPBehindIT downloads and installs it for you.</li><li>Or download it manually from <a href="https://www.docker.com/products/docker-desktop/" target="_blank" rel="noreferrer">docker.com</a> and install it yourself.</li><li>After installation, click <strong>Re-check</strong> on the Dashboard.</li></ol><h3 id="docker-desktop-is-installed-but-not-starting" tabindex="-1">Docker Desktop is installed but not starting <a class="header-anchor" href="#docker-desktop-is-installed-but-not-starting" aria-label="Permalink to &quot;Docker Desktop is installed but not starting&quot;">​</a></h3><p><strong>What you see:</strong> MCPBehindIT detects Docker but can&#39;t start it. The message says &quot;Docker Desktop was found but could not be started.&quot;</p><p><strong>Fix:</strong></p><ol><li>Open <strong>Docker Desktop</strong> manually from your Applications folder or Spotlight.</li><li>Wait until the Docker icon in the menu bar shows it&#39;s running (the whale icon stops animating).</li><li>Return to MCPBehindIT and click <strong>Re-check</strong>.</li><li>If Docker Desktop won&#39;t start, try restarting your Mac.</li></ol><h3 id="docker-auto-install-failed" tabindex="-1">Docker auto-install failed <a class="header-anchor" href="#docker-auto-install-failed" aria-label="Permalink to &quot;Docker auto-install failed&quot;">​</a></h3><p><strong>What you see:</strong> The progress bar stopped and shows an error message.</p><p><strong>Fix:</strong></p><ol><li>Check your internet connection.</li><li>Click <strong>Re-check</strong> to try again.</li><li>If it keeps failing, install Docker Desktop manually from <a href="https://www.docker.com/products/docker-desktop/" target="_blank" rel="noreferrer">docker.com</a>.</li></ol><h3 id="docker-is-running-but-mcpbehindit-shows-unavailable" tabindex="-1">Docker is running but MCPBehindIT shows &quot;Unavailable&quot; <a class="header-anchor" href="#docker-is-running-but-mcpbehindit-shows-unavailable" aria-label="Permalink to &quot;Docker is running but MCPBehindIT shows &quot;Unavailable&quot;&quot;">​</a></h3><p><strong>What you see:</strong> Docker Desktop is clearly running, but MCPBehindIT doesn&#39;t detect it.</p><p><strong>Fix:</strong></p><ol><li>Make sure Docker Desktop has fully started (wait for the whale icon to stabilize).</li><li>Click <strong>Re-check</strong> on the Dashboard.</li><li>If using <strong>Colima</strong> or another Docker-compatible runtime instead of Docker Desktop, check that the Docker socket is at the default path (<code>/var/run/docker.sock</code>).</li></ol><hr><h2 id="port-issues" tabindex="-1">Port issues <a class="header-anchor" href="#port-issues" aria-label="Permalink to &quot;Port issues&quot;">​</a></h2><h3 id="port-already-in-use" tabindex="-1">Port already in use <a class="header-anchor" href="#port-already-in-use" aria-label="Permalink to &quot;Port already in use&quot;">​</a></h3><p><strong>What you see:</strong> The port check fails with a message like &quot;Port 8000 is already in use.&quot;</p><p><strong>Fix:</strong></p><ol><li><p><strong>Option A:</strong> Find and stop whatever is using port 8000. In Terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsof</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :8000</span></span></code></pre></div><p>Then stop that process.</p></li><li><p><strong>Option B:</strong> Change the gateway port in <strong>Settings → HTTP port</strong> to an unused port (e.g., 8001).</p></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If the MCPBehindIT container itself is already running on that port, the app recognizes this and treats it as OK. This only happens when something else is using the port.</p></div><hr><h2 id="macos-issues" tabindex="-1">macOS issues <a class="header-anchor" href="#macos-issues" aria-label="Permalink to &quot;macOS issues&quot;">​</a></h2><h3 id="mcpbehindit-is-damaged-and-can-t-be-opened" tabindex="-1">&quot;MCPBehindIT is damaged and can&#39;t be opened&quot; <a class="header-anchor" href="#mcpbehindit-is-damaged-and-can-t-be-opened" aria-label="Permalink to &quot;&quot;MCPBehindIT is damaged and can&#39;t be opened&quot;&quot;">​</a></h3><p><strong>What you see:</strong> macOS shows a warning that the app is damaged.</p><p><strong>Fix:</strong> Open Terminal and run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/Applications/MCPBehindIT.app&quot;</span></span></code></pre></div><p>This clears the quarantine flag. MCPBehindIT uses ad-hoc code signing since it&#39;s not distributed through the App Store.</p><h3 id="mcpbehindit-can-t-be-opened-because-apple-cannot-check-it-for-malicious-software" tabindex="-1">&quot;MCPBehindIT can&#39;t be opened because Apple cannot check it for malicious software&quot; <a class="header-anchor" href="#mcpbehindit-can-t-be-opened-because-apple-cannot-check-it-for-malicious-software" aria-label="Permalink to &quot;&quot;MCPBehindIT can&#39;t be opened because Apple cannot check it for malicious software&quot;&quot;">​</a></h3><p><strong>Fix:</strong> Same as above — run the <code>xattr -cr</code> command. Or: right-click the app in Finder → <strong>Open</strong> → click <strong>Open</strong> in the dialog.</p><hr><h2 id="license-issues" tabindex="-1">License issues <a class="header-anchor" href="#license-issues" aria-label="Permalink to &quot;License issues&quot;">​</a></h2><h3 id="license-validation-failed" tabindex="-1">&quot;License validation failed&quot; <a class="header-anchor" href="#license-validation-failed" aria-label="Permalink to &quot;&quot;License validation failed&quot;&quot;">​</a></h3><p><strong>What you see:</strong> The activation overlay shows &quot;License validation failed.&quot;</p><p><strong>Fix:</strong></p><ol><li>Double-check your license key — no extra spaces at the beginning or end.</li><li>Make sure you have an internet connection.</li><li>If the key was already activated on another device, contact MindBehind IT.</li></ol><h3 id="license-expires-while-the-app-is-running" tabindex="-1">License expires while the app is running <a class="header-anchor" href="#license-expires-while-the-app-is-running" aria-label="Permalink to &quot;License expires while the app is running&quot;">​</a></h3><p><strong>What you see:</strong> The gateway suddenly stops and the activation overlay reappears.</p><p><strong>Fix:</strong></p><ol><li>If your license was renewed, paste the new key and click <strong>Activate</strong>.</li><li>If you think this is an error, click <strong>Check again</strong> — the validation server may have been temporarily unreachable.</li><li>Contact MindBehind IT if the issue persists.</li></ol><hr><h2 id="oauth-issues" tabindex="-1">OAuth issues <a class="header-anchor" href="#oauth-issues" aria-label="Permalink to &quot;OAuth issues&quot;">​</a></h2><h3 id="oauth-toast-appears-but-browser-didn-t-open" tabindex="-1">OAuth toast appears but browser didn&#39;t open <a class="header-anchor" href="#oauth-toast-appears-but-browser-didn-t-open" aria-label="Permalink to &quot;OAuth toast appears but browser didn&#39;t open&quot;">​</a></h3><p><strong>What you see:</strong> The &quot;OAuth sign-in required&quot; notification appears, but no browser window opened.</p><p><strong>Fix:</strong></p><ol><li>Click <strong>Copy URL</strong> on the toast.</li><li>Paste the URL into your browser manually.</li><li>Complete the sign-in process.</li><li>This can happen on some macOS configurations where opening external URLs is restricted.</li></ol><h3 id="oauth-keeps-asking-to-sign-in" tabindex="-1">OAuth keeps asking to sign in <a class="header-anchor" href="#oauth-keeps-asking-to-sign-in" aria-label="Permalink to &quot;OAuth keeps asking to sign in&quot;">​</a></h3><p><strong>What you see:</strong> Every time you restart the gateway, the OAuth toast appears again.</p><p><strong>This is normal</strong> for the first restart after token expiry. OAuth tokens have a limited lifetime. When they expire, the gateway requests a new authorization.</p><p>If it happens on <strong>every</strong> restart even shortly after signing in:</p><ol><li>Check <strong>Logs</strong> for errors related to the OAuth token exchange.</li><li>Make sure the service (e.g., Teleconsole) is properly authorized for your account.</li><li>Verify your system clock is correct (token validation is time-sensitive).</li></ol><hr><h2 id="gateway-issues" tabindex="-1">Gateway issues <a class="header-anchor" href="#gateway-issues" aria-label="Permalink to &quot;Gateway issues&quot;">​</a></h2><h3 id="gateway-won-t-start" tabindex="-1">Gateway won&#39;t start <a class="header-anchor" href="#gateway-won-t-start" aria-label="Permalink to &quot;Gateway won&#39;t start&quot;">​</a></h3><p><strong>What you see:</strong> Clicking Start doesn&#39;t work or shows an error immediately.</p><p><strong>Fix:</strong></p><ol><li>Check that Docker is running (green DOCKER indicator).</li><li>Check the port is available.</li><li>Look at the error details on the stack card.</li><li>Check <strong>Logs</strong> for container startup errors.</li><li>Try <strong>Apply &amp; Restart</strong> to force a fresh container.</li></ol><h3 id="successfully-connected-but-tools-don-t-work-in-my-ai-client" tabindex="-1">&quot;Successfully connected&quot; but tools don&#39;t work in my AI client <a class="header-anchor" href="#successfully-connected-but-tools-don-t-work-in-my-ai-client" aria-label="Permalink to &quot;&quot;Successfully connected&quot; but tools don&#39;t work in my AI client&quot;">​</a></h3><p><strong>Fix:</strong></p><ol><li>Verify the server appears on the <strong>Clients</strong> tab.</li><li>Copy the <strong>OpenAPI</strong> URL and open it in your browser — you should see a JSON spec.</li><li>Make sure your AI tool is configured with the correct URL.</li><li>If using Open WebUI, use <code>localhost</code> instead of <code>127.0.0.1</code>.</li></ol><hr><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck?&quot;">​</a></h2><ol><li>Check <strong>Logs</strong> for any error messages.</li><li>Enable <strong>Advanced mode</strong> in Settings and review the generated config.</li><li>Try stopping the gateway, waiting 10 seconds, and starting it again.</li><li>Restart Docker Desktop.</li><li>Contact MindBehind IT support with your log output and config (from Advanced mode).</li></ol>',68)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
